VAR Medida_pj = 'Medidas'[ToquesArea]

VAR Medida_Total = CALCULATE(
    AVERAGEX('Tb_SerieC25', 'Medidas'[ToquesArea]),
    FILTER(
        ALL('Tb_SerieC25'),
        'Tb_SerieC25'[Posição] IN {"Extremo Direito", "Extremo Esquerdo"}
        && 'Tb_SerieC25'[Minutos jogados:] > 400
    )
)

VAR Medida_DP = CALCULATE(
    STDEVX.S('Tb_SerieC25', 'Medidas'[ToquesArea]),
    FILTER(
        ALL('Tb_SerieC25'),
        'Tb_SerieC25'[Posição] IN {"Extremo Direito", "Extrmo Esquerdo"}
        && 'Tb_SerieC25'[Minutos jogados:] > 400
    )
)

RETURN

(Medida_pj - Medida_Total)/Medida_DP

